    s.append("    dw_Press_System_Status_Word      : DWORD; (* Primary press system diagnostic status word *)")
    s.append("    dw_TMR_Health_Bitmask_1          : DWORD; (* 2oo3 TMR sensor channels 1..16 health status *)")
    s.append("    dw_TMR_Health_Bitmask_2          : DWORD; (* 2oo3 TMR sensor channels 17..32 health status *)")
    s.append("    dw_ISA_Alarm_Word_HI_HI          : DWORD; (* ISA-18.2 Priority 1 Critical Trip Alarm Bitmask *)")
    s.append("    dw_ISA_Alarm_Word_HI             : DWORD; (* ISA-18.2 Priority 2 Warning Alarm Bitmask *)")
    s.append("    dw_ISA_Alarm_Word_LO             : DWORD; (* ISA-18.2 Priority 3 Low Advisory Alarm Bitmask *)")
    s.append("    dw_ISA_Alarm_Word_LO_LO          : DWORD; (* ISA-18.2 Priority 4 Critical Low Alarm Bitmask *)")
    s.append("    dw_ISA_Alarm_Word_ROC            : DWORD; (* ISA-18.2 Priority 5 Rate-Of-Change Anomaly Bitmask *)")
    s.append("    r_Estimated_Flue_LEL_Percent     : REAL;  (* Observer-estimated solvent vapor concentration [% LEL] *)")
    s.append("    r_Max_Registration_Circ_Error_MM : REAL;  (* Maximum absolute circumferential error [mm] *)")
    s.append("    r_Max_Registration_Lat_Error_MM  : REAL;  (* Maximum absolute lateral error [mm] *)")
    s.append("    r_Effective_Web_Modulus_MPA      : REAL;  (* Kelvin-Voigt dynamic paper modulus [MPa] *)")
    s.append("    r_Chill_Roll_Dewpoint_Margin_C   : REAL;  (* Temperature margin above condensation dewpoint [deg C] *)")
    s.append("    r_MPC_Cumulative_Cost_Val        : REAL;  (* Receding-horizon MPC quadratic cost function value *)")
    s.append("END_VAR")
    s.append("")
    return "\n".join(s)
